import './styles.css';

const SCOPES = { cell:'Cell', row:'Row', column:'Column', box:'Box', grid:'Entire Grid' };
const state = { section:'home', phase:'input', personal:null, dc:[], dcIndex:0, selected:40, mode:'number', scope:'cell', history:[], message:'', hint:null, wrong:new Set(),showImage:false,showHelp:false,nudge:null,cellUndo:null,pop:-1,dataDate:'',editBackup:null };
function buzz(ms){try{if(navigator.vibrate) navigator.vibrate(ms);}catch{}}
const R=i=>Math.floor(i/9), C=i=>i%9, I=(r,c)=>r*9+c, B=i=>Math.floor(R(i)/3)*3+Math.floor(C(i)/3);
const blank=()=>Array.from({length:81},()=>({value:0,given:false,candidates:new Set()}));
const makePuzzle=(raw,source)=>({id:raw.id||`p-${Date.now()}`,title:raw.title||'My Sudoku',verified:!!raw.verified,source,image:raw.image||'',cells:(raw.grid||Array.from({length:9},()=>Array(9).fill(0))).flat().map(v=>({value:v,given:v!==0,candidates:new Set()}))});
const active=()=>state.section==='personal'?state.personal:state.dc[state.dcIndex];
function peers(i){const out=[];for(let j=0;j<81;j++)if(j!==i&&(R(j)===R(i)||C(j)===C(i)||B(j)===B(i)))out.push(j);return out;}
function region(scope,i){if(scope==='cell')return[i];if(scope==='row')return Array.from({length:9},(_,c)=>I(R(i),c));if(scope==='column')return Array.from({length:9},(_,r)=>I(r,C(i)));if(scope==='grid')return Array.from({length:81},(_,x)=>x);const br=Math.floor(R(i)/3)*3,bc=Math.floor(C(i)/3)*3,a=[];for(let r=0;r<3;r++)for(let c=0;c<3;c++)a.push(I(br+r,bc+c));return a;}
function legalCandidates(p,i){if(p.cells[i].value||p.cells[i].given)return[];return Array.from({length:9},(_,k)=>k+1).filter(n=>peers(i).every(j=>p.cells[j].value!==n));}
function conflicts(){const p=active(),bad=new Set();if(!p)return bad;for(let i=0;i<81;i++){const n=p.cells[i].value;if(!n)continue;for(const j of peers(i))if(p.cells[j].value===n){bad.add(i);bad.add(j);}}return bad;}
function solveGrid(values){const a=values.slice();const can=(pos,n)=>{const r=R(pos),c=C(pos);for(let k=0;k<9;k++)if(a[I(r,k)]===n||a[I(k,c)]===n)return false;const br=Math.floor(r/3)*3,bc=Math.floor(c/3)*3;for(let rr=0;rr<3;rr++)for(let cc=0;cc<3;cc++)if(a[I(br+rr,bc+cc)]===n)return false;return true;};const dfs=()=>{let best=-1,opts=null;for(let i=0;i<81;i++)if(!a[i]){const o=[];for(let n=1;n<=9;n++)if(can(i,n))o.push(n);if(!o.length)return false;if(!opts||o.length<opts.length){best=i;opts=o;if(o.length===1)break;}}if(best<0)return true;for(const n of opts){a[best]=n;if(dfs())return true;a[best]=0;}return false;};return dfs()?a:null;}
function givensSolution(p){return solveGrid(p.cells.map(c=>c.given?c.value:0));}
function wrongEntries(){const p=active(),bad=new Set();if(!p)return bad;conflicts().forEach(i=>bad.add(i));const solution=givensSolution(p);if(!solution)return bad;for(let i=0;i<81;i++){const c=p.cells[i];if(c.value&&!c.given&&c.value!==solution[i])bad.add(i);}return bad;}
function hintCandidate(){const p=active();if(!p)return null;const open=Array.from({length:81},(_,i)=>i).filter(i=>!p.cells[i].value&&!p.cells[i].given);if(!open.length)return null;const scored=open.map(i=>({i,opts:legalCandidates(p,i)})).filter(x=>x.opts.length);for(const x of scored)if(x.opts.length===1)return {index:x.i,value:x.opts[0],reason:'Only possible number for this cell'};const units=[];for(let r=0;r<9;r++)units.push(Array.from({length:9},(_,c)=>I(r,c)));for(let c=0;c<9;c++)units.push(Array.from({length:9},(_,r)=>I(r,c)));for(let br=0;br<9;br+=3)for(let bc=0;bc<9;bc+=3){const u=[];for(let r=0;r<3;r++)for(let c=0;c<3;c++)u.push(I(br+r,bc+c));units.push(u);}for(const unit of units)for(let n=1;n<=9;n++){const spots=unit.filter(i=>!p.cells[i].value&&!p.cells[i].given&&legalCandidates(p,i).includes(n));if(spots.length===1)return {index:spots[0],value:n,reason:'Only place for this number in its row, column, or box'};}scored.sort((a,b)=>a.opts.length-b.opts.length||a.i-b.i);const best=scored[0];if(!best)return null;const s=solveGrid(p.cells.map(c=>c.value));if(!s)return null;return {index:best.i,value:s[best.i],reason:`A valid next move from the current grid (${best.opts.length} candidates)`};}
function snap(p){return JSON.stringify({id:p.id,title:p.title,verified:p.verified,source:p.source,image:p.image,cells:p.cells.map(c=>({value:c.value,given:c.given,candidates:[...c.candidates]}))});}
function restore(s){return {id:s.id,title:s.title,verified:s.verified,source:s.source,image:s.image||'',cells:s.cells.map(c=>({value:c.value,given:c.given,candidates:new Set(c.candidates)}))};}
function push(){const p=active();if(p)state.history.push(snap(p));state.cellUndo=null;}
function undo(){const s=state.history.pop();if(!s){state.message='Nothing to undo.';return render();}const p=restore(JSON.parse(s));if(state.section==='personal')state.personal=p;else state.dc[state.dcIndex]=p;state.wrong=new Set();state.hint=null;state.nudge=null;state.cellUndo=null;state.message='Undid the last change.';render();}function cellUndoApply(){const cu=state.cellUndo;if(!cu){return render();}const p=active(),c=p.cells[cu.index];if(c&&!c.given&&c.value===cu.value){push();c.value=0;c.candidates=new Set(cu.candidates.filter(v=>v!==cu.value));}state.cellUndo=null;state.wrong=wrongEntries();state.pop=cu.index;setTimeout(()=>{state.pop=-1;render();},320);buzz(15);set('Undid the wrong entry; candidates restored.');render();}function cellUndoChip(p,input){const cu=state.cellUndo;if(!cu||input||!p)return '';const cc=p.cells[cu.index];if(!cc||cc.value!==cu.value||cc.given)return '';return `<button class="cell-undo" data-cellundo="${cu.index}" style="left:calc(${(C(cu.index)+1)/9*100}% - 34px);top:calc(${R(cu.index)/9*100}% + 2px)" title="Undo ${cu.value} here and restore its candidates" aria-label="Undo wrong entry at R${R(cu.index)+1}C${C(cu.index)+1}">↩</button>`;}
function set(m){state.message=m;}
function enter(n){const p=active(),c=p.cells[state.selected];state.hint=null;state.nudge=null;state.cellUndo=null;if(state.section==='personal'&&state.phase==='input'){if(c.value){set('That cell already has a number. Use Clear Cell to correct it.');buzz(35);return render();}push();c.value=n;c.given=true;set(`Added ${n} to R${R(state.selected)+1}C${C(state.selected)+1}.`);state.pop=state.selected;setTimeout(()=>{state.pop=-1;render();},320);buzz(15);return render();}if(c.given){set('Source numbers cannot be changed.');buzz(35);return render();}if(!peers(state.selected).every(j=>p.cells[j].value!==n)){{const rr=R(state.selected),cc=C(state.selected);let where='this row, column or box';if(p.cells.some((x,j)=>j!==state.selected&&R(j)===rr&&x.value===n))where=`row ${rr+1}`;else if(p.cells.some((x,j)=>j!==state.selected&&C(j)===cc&&x.value===n))where=`column ${cc+1}`;else where='its 3x3 box';set(`${n} can't go here — already in ${where}. Red cells mark the clash.`);}buzz(40);state.wrong=wrongEntries();return render();}push();const prevCands=[...c.candidates];c.value=n;c.candidates.clear();const sol=givensSolution(p);if(sol&&sol[state.selected]===n){peers(state.selected).forEach(j=>p.cells[j].candidates.delete(n));state.cellUndo=null;buzz(15);set(`Placed ${n} at R${R(state.selected)+1}C${C(state.selected)+1}.`);}else if(sol){state.cellUndo={index:state.selected,value:n,candidates:prevCands};buzz(40);set(`${n} looks wrong in R${R(state.selected)+1}C${C(state.selected)+1} — other candidates untouched. Tap ↩ on the cell to undo.`);}else{peers(state.selected).forEach(j=>p.cells[j].candidates.delete(n));buzz(15);set(`Placed ${n} at R${R(state.selected)+1}C${C(state.selected)+1}.`);}state.wrong=wrongEntries();state.pop=state.selected;setTimeout(()=>{state.pop=-1;render();},320);render();}
function candidate(n){if(state.phase==='input'){set('Confirm the puzzle first.');return render();}const p=active(),ids=region(state.scope,state.selected).filter(i=>!p.cells[i].value&&!p.cells[i].given),valid=ids.filter(i=>peers(i).every(j=>p.cells[j].value!==n));if(!valid.length){set(`${n} is not legal in this scope.`);return render();}push();const add=valid.some(i=>!p.cells[i].candidates.has(n));valid.forEach(i=>add?p.cells[i].candidates.add(n):p.cells[i].candidates.delete(n));set(`${add?'Added':'Removed'} ${n} in ${SCOPES[state.scope].toLowerCase()}.`);render();}
function fillAll(p){p.cells.forEach((c,i)=>{if(!c.value&&!c.given)c.candidates=new Set(legalCandidates(p,i));});}function auto(){if(state.phase==='input'){set('Confirm the puzzle first.');return render();}const p=active(),ids=region(state.scope,state.selected).filter(i=>!p.cells[i].value&&!p.cells[i].given);if(!ids.length){set('No editable cells in this scope.');return render();}push();ids.forEach(i=>p.cells[i].candidates=new Set(legalCandidates(p,i)));set(`Auto candidates generated for ${ids.length} cells.`);render();}
function clearCell(){const p=active(),c=p.cells[state.selected];state.hint=null;state.nudge=null;state.cellUndo=null;if(c.given&&state.phase!=='input'){set('Source numbers cannot be cleared.');return render();}push();c.value=0;c.given=false;c.candidates.clear();state.wrong=wrongEntries();set(`Cleared R${R(state.selected)+1}C${C(state.selected)+1}.`);render();}
function solveScope(){if(state.phase==='input'){set('Confirm the puzzle first.');return render();}const p=active();if(conflicts().size){state.wrong=wrongEntries();set('Fix the red conflicting entries before solving.');return render();}const s=solveGrid(p.cells.map(c=>c.value));if(!s){state.wrong=wrongEntries();set('The puzzle cannot be solved from the current entries.');return render();}const ids=region(state.scope,state.selected).filter(i=>!p.cells[i].given&&!p.cells[i].value);if(!ids.length){set('There are no empty editable cells in this scope.');return render();}push();ids.forEach(i=>{p.cells[i].value=s[i];p.cells[i].candidates.clear();});state.wrong=new Set();state.hint=null;state.nudge=null;set(`Solved ${state.scope==='cell'?'the selected cell':`the selected ${SCOPES[state.scope].toLowerCase()}`}.`);render();}
function check(){const p=active(),bad=wrongEntries();state.wrong=bad;if(bad.size){const coords=[...bad].slice(0,4).map(i=>`R${R(i)+1}C${C(i)+1}`).join(', ');set(`These entries are wrong: ${coords}. Red cells mark a conflict or a value that disagrees with the solution determined by the printed givens.`);}else{const s=solveGrid(p.cells.map(c=>c.value));set(s?(p.cells.every(c=>c.value)?'Puzzle complete and valid.':'Current entries are consistent with the puzzle.'):'The current entries are not solvable.');}render();}
function hint(){if(state.phase==='input'){set('Confirm the puzzle first.');return render();}const h=hintCandidate();if(!h){set('No next move can be derived from the current grid.');return render();}state.selected=h.index;state.hint=h;state.nudge=null;set(`Hint: put ${h.value} in R${R(h.index)+1}C${C(h.index)+1}. ${h.reason}.`);render();}
function save(){try{localStorage.setItem('dcsudoku-v1',JSON.stringify({personal:state.personal?snap(state.personal):null,personalPhase:state.phase,dcDate:state.dataDate,dcIndex:state.dcIndex,dcSnaps:state.dc.map(snap)}));}catch{}}
function readSave(){try{const s=localStorage.getItem('dcsudoku-v1');return s?JSON.parse(s):null;}catch{return null;}}
function myPuzzle(){if(state.personal){state.section='personal';if(state.phase!=='input'&&state.phase!=='solve')state.phase='solve';set(state.phase==='input'?'Continue adding the printed numbers.':'Welcome back — continue your puzzle.');render();}else startPersonal();}
function editGivens(){if(!state.personal||state.section!=='personal'||state.phase!=='solve')return render();state.editBackup=snap(state.personal);state.phase='input';state.history=[];state.hint=null;state.nudge=null;state.cellUndo=null;set('Edit the printed numbers, then choose Done Editing. Cancel restores your solving.');render();}
function cancelEdit(){if(state.editBackup){try{state.personal=restore(JSON.parse(state.editBackup));}catch{}}state.editBackup=null;state.phase='solve';state.history=[];state.hint=null;state.nudge=null;state.cellUndo=null;set('Edits cancelled — back to solving.');render();}
async function refresh(){set('Refreshing daily puzzles…');render();await load(true);}
function confirm(){const p=active();if(conflicts().size){set('These entries conflict. Recheck the numbers.');return render();}if(!p.cells.some(c=>c.value)){set('Enter at least one printed number first.');return render();}if(!solveGrid(p.cells.map(c=>c.value))){set('These entries do not form a solvable puzzle. Recheck the numbers.');return render();}state.phase='solve';state.editBackup=null;state.history=[];state.mode='number';state.scope='cell';state.hint=null;state.nudge=null;state.cellUndo=null;state.wrong=new Set();fillAll(p);set('Puzzle confirmed. Auto candidates filled — you can now solve it.');render();}
function startPersonal(){state.personal={id:`personal-${Date.now()}`,title:'My Sudoku',verified:true,source:'TOI / Printed',image:'',cells:blank()};state.section='personal';state.phase='input';state.selected=40;state.mode='number';state.scope='cell';state.history=[];state.hint=null;state.nudge=null;state.cellUndo=null;state.editBackup=null;state.wrong=new Set();set('Step 1: Add the numbers already printed in the newspaper.');render();}
function dc(){state.section='dc';state.phase='solve';state.dcIndex=0;state.selected=40;state.history=[];state.mode='number';state.scope='cell';state.hint=null;state.nudge=null;state.cellUndo=null;state.wrong=new Set();set('Deccan Chronicle puzzles ready.');render();}
function renderHome(){document.querySelector('#app').innerHTML=`<div class="home"><div class="eyebrow">SUDOKU COMPANION</div><h1>Your puzzles.<br>Your way.</h1><p>Bring a TOI/printed puzzle or play the daily Deccan Chronicle puzzles.</p><div class="home-grid"><button id="myHome" class="home-card"><small>MY SUDOKU</small><strong>Enter a printed puzzle</strong><span>Type the givens, confirm once, then solve it.</span><b>Start my puzzle →</b></button><button id="dcHome" class="home-card dc"><small>DECCAN CHRONICLE</small><strong>Daily Sudoku</strong><span>Today's Hyderabad puzzles from the backend pipeline.</span><b>Open today's puzzles →</b></button></div><button data-help class="home-guide">? New here — how to use this app</button></div>${state.showHelp?helpHtml():''}`;wire();}
function render(){if(state.section==='home')return renderHome();const p=active(),bad=wrongEntries(),input=state.section==='personal'&&state.phase==='input';if(!p){document.querySelector('#app').innerHTML=`<div class="screen"><header class="header"><div><div class="eyebrow">DECCAN CHRONICLE</div><div class="app-name">No puzzles</div><div class="sub">Check connection</div></div><span class="top-btns"><button id="helpBtn" class="aa help" title="Help">?</button><button id="aa" class="aa" title="Toggle large text">Aa</button></span></header><div class="dc-bar"><span>${state.dataDate||'Offline'}</span><button data-refresh title="Retry">↻ Retry</button></div><div class="skeleton"><div class="sk-board"></div><div class="sk-row"></div><div class="sk-row short"></div></div><div class="message bad" aria-live="polite">${state.message||'Could not load daily puzzles. Tap Retry when back online.'}</div><button data-refresh class="confirm" style="margin-top:8px">↻ Try again</button></div>`;wire();return;}const relatedHint=state.hint&&state.hint.index;const isDc=state.section==='dc'&&p.image&&state.showImage;const boardClass=isDc?'board image-board':'board';const selVal=p.cells[state.selected]?p.cells[state.selected].value:0;const counts=Array.from({length:9},(_,k)=>p.cells.filter(x=>x.value===k+1).length);const blocked=input?[]:Array.from({length:9},(_,k)=>!peers(state.selected).every(j=>p.cells[j].value!==k+1));const scopeIds=input?new Set():new Set(region(state.scope,state.selected));const solved=!input&&p.cells.every(x=>x.value)&&!bad.size;document.querySelector('#app').innerHTML=`<div class="screen"><header class="header"><div><div class="eyebrow">${input?'MY SUDOKU':state.section==='personal'?'MY SUDOKU':'DECCAN CHRONICLE'}</div><div class="app-name">${input?'Enter Puzzle':p.title}</div><div class="sub">${input?'Step 1 · Add printed numbers':state.section==='personal'?'Step 2 · Solve your puzzle':'Hyderabad · Daily'}</div></div><span class="top-btns"><button id="helpBtn" class="aa help" title="Help: what each button does" aria-label="Help">?</button><button id="aa" class="aa" title="Toggle large text" aria-label="Toggle large text">Aa</button></span></header><div class="source-tabs"><button id="dcTab" title="Daily Deccan Chronicle puzzles" class="${state.section==='dc'?'active':''}"><strong>Deccan Chronicle</strong><small>Daily</small></button><button id="myTab" title="Your own printed puzzles" class="${state.section==='personal'?'active':''}"><strong>My Sudoku</strong><small>TOI / Print</small></button></div>${state.section==='dc'?`<div class="puzzle-tabs">${state.dc.map((x,i)=>`<button data-puzzle="${i}" class="${i===state.dcIndex?'active':''}"><strong>${x.title}</strong><small>${x.verified?'Verified':'Imported'}</small></button>`).join('')}</div><div class="dc-bar"><span>Updated ${state.dataDate||'…'}</span><button data-refresh title="Download today's puzzles">↻ Refresh</button><button data-img title="Show the newspaper photo behind the grid">${state.showImage?'Hide photo':'Show photo'}</button></div>`:''}${input?`<div class="step"><b>1</b><div><strong>Add the printed numbers</strong><span>Tap a cell, then its number. Clear Cell corrects an entry. <b>${p.cells.filter(c=>c.value).length} added</b> — copy every printed number (at least 17), then press Confirm.</span></div></div>`:''}${!input&&state.section==='personal'?`<div class="step confirmed"><b>2</b><div><strong>Puzzle confirmed</strong><span>The puzzle is solvable. You are now in solve mode.</span></div></div>`:''}${!input&&state.nudge?`<div class="nudge-banner" role="status"><div><strong>${state.nudge.kind==='naked'?`Nudge: only one number fits in R${R(state.nudge.index)+1}C${C(state.nudge.index)+1}`:`Nudge: find ${state.nudge.value} in the highlighted ${unitLabel(state.nudge.unit,state.nudge.unitIndex)}`}</strong><span>${state.nudge.reason} ${state.nudge.kind==='naked'?'Check the row, column and box — what is left?':'Tap a highlighted cell when you spot it.'}</span></div><button data-nudge-fill>${state.nudge.kind==='naked'?'Reveal':'Fill hint'}</button><button data-nudge-off>Got it</button></div>`:''}<div class="board-wrap"><div class="${boardClass}">${isDc?`<img class="board-image" src="${p.image}" alt="${p.title} source image" loading="eager">`:''}${p.cells.map((c,i)=>{const rel=R(i)===R(state.selected)||C(i)===C(state.selected)||B(i)===B(state.selected);const hinted=relatedHint===i;const valueVisible=!isDc||!c.given;return `<button class="cell ${rel?'related':''} ${i===state.selected?'selected':''} ${bad.has(i)?'invalid':''} ${hinted?'hinted':''} ${state.nudge&&state.nudge.cells.includes(i)?'nudged':''} ${!input&&scopeIds.has(i)&&i!==state.selected?'scope-preview':''} ${state.pop===i?'pop':''} ${!hinted&&!bad.has(i)&&selVal&&c.value===selVal?'same':''}" data-cell="${i}" aria-label="R${R(i)+1}C${C(i)+1}">${valueVisible&&c.value?`<span class="value ${c.given?'given':'user'}">${c.value}</span>`:!input&&c.candidates.size?`<span class="notes">${Array.from({length:9},(_,k)=>`<i>${c.candidates.has(k+1)?k+1:''}</i>`).join('')}</span>`:''}${hinted?`<span class="hint-badge">${state.hint.value}</span>`:''}</button>`}).join('')}${state.hint?`<div class="hint-popover" data-hint-cell="${state.hint.index}"><strong>Try ${state.hint.value}</strong><span>R${R(state.hint.index)+1}C${C(state.hint.index)+1} · ${state.hint.reason}</span></div>`:''}</div>${cellUndoChip(p,input)}</div>${isDc&&state.showImage?`<div class="photo-hint">Photo mode — givens hidden. <b>Hide photo</b> to see the numbers.</div>`:''}${!input?`<div class="stats"><span>${p.cells.filter(x=>x.value).length}/81 filled</span><span>✕ ${bad.size} wrong</span></div>`:''}${solved?`<div class="solved-banner"><strong>✓ Solved — nicely done!</strong>${state.section==='personal'?`<button data-new>Start new puzzle</button>`:`<span>New puzzles load automatically each day.</span>`}</div>`:''}<section class="controls">${input?`<button id="confirm" class="confirm" title="Validate the givens and start solving">${state.editBackup?'Done Editing':'Confirm Puzzle'}</button>${state.editBackup?`<button id="cancelEdit" class="cancel" title="Discard edits and resume solving">Cancel</button>`:''}`:`<div class="ctl-cap">Number places digits · Candidates adds pencil marks · Scope picks where Hint, Solve and Auto act</div><div class="mode-row"><div class="segmented"><button id="numberMode" title="Place final digits" class="${state.mode==='number'?'active':''}">Number</button><button id="candidateMode" title="Toggle small pencil-mark candidates instead of digits" class="${state.mode==='candidate'?'active':''}">Candidates</button></div><div class="scope-row">${Object.entries(SCOPES).map(([k,v])=>`<button data-scope="${k}" title="Scope: the area Hint, Nudge, Solve and Auto apply to" class="scope ${state.scope===k?'active':''}">${v}</button>`).join('')}</div></div>`}<div class="number-pad">${Array.from({length:9},(_,i)=>{const n=i+1,left=9-counts[i];return `<button data-number="${n}" title="Place ${n}" class="${!input&&blocked[i]?'blocked':''} ${!input&&left<=0?'done':''}">${n}<small>${left}</small></button>`}).join('')}</div>${!input?`<div class="legend">Small number = left to place · <s>struck</s> = can't go in this cell · dimmed = all 9 placed</div>`:''}<div class="actions">${input?`<button id="clear" title="Empty the selected cell">Clear Cell</button><button id="undo" title="Take back the last change">Undo</button><button id="switchDc" title="Open the daily Deccan Chronicle puzzles">DC Puzzles</button>`:`<button id="clear" title="Empty the selected cell">Clear Cell</button><button id="undo" title="Take back the last change">Undo</button>${state.section==='personal'?`<button id="editGivens" title="Go back and fix the printed numbers">Edit givens</button>`:''}<button id="auto" title="Fill in all pencil marks for the selected scope">Auto Candidates</button><button id="solve" class="primary" title="Fill the correct digits in the selected scope">Solve ${SCOPES[state.scope]}</button><button id="hint" title="Suggest one easy move and explain why">Hint</button><button id="nudge" title="Highlight the row, column or box to look at — exact cell stays hidden">Nudge</button><button id="check" title="Verify your entries against the solution">Check</button>${state.section==='personal'?`<button id="newPersonal" title="Start a fresh puzzle">New</button>`:''}`}</div><div class="message" aria-live="polite">${state.message}</div></section>${state.showHelp?helpHtml():''}</div>`;save();wire();}
function wire(){const r=document.querySelector('#app');r.querySelector('#myHome')?.addEventListener('click',myPuzzle);r.querySelector('#dcHome')?.addEventListener('click',dc);r.querySelector('#dcTab')?.addEventListener('click',dc);r.querySelector('#myTab')?.addEventListener('click',myPuzzle);r.querySelector('#aa')?.addEventListener('click',()=>document.body.classList.toggle('large-mode'));r.querySelector('#helpBtn')?.addEventListener('click',()=>{state.showHelp=true;render();});r.querySelector('#helpClose')?.addEventListener('click',()=>{state.showHelp=false;render();});r.querySelector('[data-help-backdrop]')?.addEventListener('click',()=>{state.showHelp=false;render();});r.querySelector('.help-card')?.addEventListener('click',e=>e.stopPropagation());r.querySelectorAll('[data-help]').forEach(b=>b.addEventListener('click',()=>{state.showHelp=true;render();}));r.querySelector('#nudge')?.addEventListener('click',nudge);r.querySelector('[data-nudge-off]')?.addEventListener('click',()=>{state.nudge=null;render();});r.querySelector('[data-nudge-fill]')?.addEventListener('click',()=>{const n=state.nudge;if(!n) return;if(n.kind==='naked'){state.selected=n.index;state.nudge=null;enter(n.value);} else {const p=active();const s=solveGrid(p.cells.map(c=>c.value));if(!s){state.message='Could not solve from current entries.';return render();}const target=n.cells.find(i=>s[i]===n.value) ?? n.cells.find(i=>!p.cells[i].value&&!p.cells[i].given) ?? n.cells[0];const c=p.cells[target];if(c.given||c.value){state.nudge=null;return render();}state.nudge=null;state.selected=target;push();c.value=n.value;c.candidates.clear();peers(target).forEach(j=>p.cells[j].candidates.delete(n.value));state.wrong=wrongEntries();set(`Placed ${n.value} for the nudge.`);render();}});r.querySelector('#confirm')?.addEventListener('click',confirm);r.querySelector('#cancelEdit')?.addEventListener('click',cancelEdit);r.querySelector('#editGivens')?.addEventListener('click',editGivens);r.querySelector('#newPersonal')?.addEventListener('click',startPersonal);r.querySelector('[data-refresh]')?.addEventListener('click',refresh);r.querySelector('[data-img]')?.addEventListener('click',()=>{state.showImage=!state.showImage;render();});r.querySelector('[data-new]')?.addEventListener('click',startPersonal);r.querySelector('#switchDc')?.addEventListener('click',dc);r.querySelectorAll('[data-puzzle]').forEach(b=>b.addEventListener('click',()=>{state.dcIndex=Number(b.dataset.puzzle);state.selected=40;state.history=[];state.hint=null;state.nudge=null;state.cellUndo=null;state.wrong=new Set();render();}));r.querySelectorAll('[data-cell]').forEach(b=>b.addEventListener('click',()=>{state.selected=Number(b.dataset.cell);state.hint=null;state.nudge=null;set(`R${R(state.selected)+1}C${C(state.selected)+1} selected.`);render();}));r.querySelector('#numberMode')?.addEventListener('click',()=>{state.mode='number';state.hint=null;state.nudge=null;render();});r.querySelector('#candidateMode')?.addEventListener('click',()=>{state.mode='candidate';state.hint=null;state.nudge=null;render();});r.querySelectorAll('[data-scope]').forEach(b=>b.addEventListener('click',()=>{state.scope=b.dataset.scope;state.hint=null;state.nudge=null;set(`Scope: ${SCOPES[state.scope]}`);render();}));r.querySelectorAll('[data-number]').forEach(b=>b.addEventListener('click',()=>{const n=Number(b.dataset.number);state.mode==='candidate'?candidate(n):enter(n);}));r.querySelector('#clear')?.addEventListener('click',clearCell);r.querySelector('#undo')?.addEventListener('click',undo);r.querySelector('[data-cellundo]')?.addEventListener('click',e=>{e.stopPropagation();cellUndoApply();});r.querySelector('#auto')?.addEventListener('click',auto);r.querySelector('#solve')?.addEventListener('click',solveScope);r.querySelector('#hint')?.addEventListener('click',hint);r.querySelector('#check')?.addEventListener('click',check);}
function allUnits(){const u=[];for(let r=0;r<9;r++)u.push({type:'row',index:r,cells:Array.from({length:9},(_,c)=>I(r,c))});for(let c=0;c<9;c++)u.push({type:'column',index:c,cells:Array.from({length:9},(_,r)=>I(r,c))});for(let b=0;b<9;b++){const br=Math.floor(b/3)*3,bc=(b%3)*3,a=[];for(let r=0;r<3;r++)for(let c=0;c<3;c++)a.push(I(br+r,bc+c));u.push({type:'box',index:b,cells:a});}return u;}
const BOX_NAMES=['top-left','top-middle','top-right','middle-left','centre','middle-right','bottom-left','bottom-middle','bottom-right'];
function unitLabel(t,i){return t==='row'?`row ${i+1}`:t==='column'?`column ${i+1}`:`${BOX_NAMES[i]||''} box`;}
function nudgeKey(n){return n?`${n.kind}:${n.unit||n.index}:${n.value}`:'';}
function findNudges(){
  const p=active();if(!p) return [];
  const candCache=new Map(); // index -> legalCandidates
  const cand=(i)=>{let c=candCache.get(i);if(c) return c;c=legalCandidates(p,i);candCache.set(i,c);return c;};
  // solution for verification: ensures every nudge is on the true solution path and therefore fillable
  let sol=null;
  try{const vals=p.cells.map(c=>c.value);if(!conflicts().size) sol=solveGrid(vals);}catch{}
  const singles=[]; // naked single: exactly 1 candidate
  for(let i=0;i<81;i++){const c=p.cells[i];if(c.value||c.given) continue;const opts=cand(i);if(opts.length===1){
    if(sol && sol[i]!==opts[0]) continue;
    singles.push({kind:'naked',value:opts[0],index:i,cells:[i],unit:null,unitIndex:null,candidateCount:1,reason:`Only ${opts[0]} can go in R${R(i)+1}C${C(i)+1}. Can you see why?`});
  }}
  if(singles.length){
    singles.sort((a,b)=>a.index-b.index);
    return singles;
  }
  const out=[]; // hidden single: number locked to 1-3 cells in a unit
  for(const u of allUnits()){
    for(let n=1;n<=9;n++){
      if(u.cells.some(i=>p.cells[i].value===n)) continue;
      const spots=u.cells.filter(i=>{const c=p.cells[i];return !c.value&&!c.given&&cand(i).includes(n);});
      if(spots.length<1||spots.length>3) continue;
      if(sol && !spots.some(i=>sol[i]===n)) continue;
      if(spots.length===1) out.push({kind:'hidden',value:n,unit:u.type,unitIndex:u.index,cells:spots,candidateCount:1,reason:`${n} must go in ${unitLabel(u.type,u.index)} — only one cell can take it.`});
      else out.push({kind:'hidden',value:n,unit:u.type,unitIndex:u.index,cells:spots,candidateCount:spots.length,reason:`${n} must go somewhere in ${unitLabel(u.type,u.index)}. Only ${spots.length} cells can take it.`});
    }
  }
  out.sort((a,b)=>a.candidateCount-b.candidateCount||(a.unitIndex*10+a.value)-(b.unitIndex*10+b.value));
  return out;
}
function nudge(){if(state.section==='personal'&&state.phase==='input'){set('Confirm the puzzle first.');return render();}const list=findNudges();if(!list.length){state.nudge=null;set('No nudge available — try Hint for an exact move, or run Auto Candidates first.');return render();}const cur=nudgeKey(state.nudge);state.nudge=list.find(n=>nudgeKey(n)!==cur)||list[0];state.hint=null;const n=state.nudge;if(n.kind==='naked') set(`Nudge: look at R${R(n.index)+1}C${C(n.index)+1} — it has only one possible number. Which one?`); else if(n.candidateCount===1) set(`Nudge: ${n.value} must go in ${unitLabel(n.unit,n.unitIndex)} — one highlighted cell is the answer.`); else set(`Nudge: find where ${n.value} goes in ${unitLabel(n.unit,n.unitIndex)}. ${n.cells.length} highlighted cells can take it — one of them is the answer.`);render();}
function helpHtml(){return `<div class="help-backdrop" data-help-backdrop><div class="help-card" role="dialog" aria-modal="true" aria-label="Help and tips"><button id="helpClose" class="help-close">Close ✕</button><h2>How to use this app</h2><h3>My Sudoku (printed puzzles)</h3><ol><li>Add every printed number: tap a cell, then its digit.</li><li>Press Confirm — the app checks the puzzle is solvable.</li><li>Solve it. Copied a number wrong? Use Edit givens.</li></ol><h3>Deccan Chronicle (daily)</h3><ol><li>Pick Sudoku 1 or 2.</li><li>Solve. Fresh puzzles arrive daily — Refresh reloads, Show photo toggles the newspaper clipping.</li></ol><h3>What each button does</h3><dl class="help-list"><dt>1–9 pad</dt><dd>Place the digit (or pencil mark) in the selected cell. Small number = how many are left. Struck = cannot go here. Dimmed = all 9 placed.</dd><dt>Number / Candidates</dt><dd>Switch between final digits and small pencil marks.</dd><dt>Cell · Row · Column · Box · Entire Grid</dt><dd>Scope: the area that Hint, Nudge, Solve and Auto Candidates work on.</dd><dt>Auto Candidates</dt><dd>Fill all legal pencil marks in the scope.</dd><dt>Solve</dt><dd>Fill the correct digits in the scope.</dd><dt>Hint</dt><dd>Reveal one exact move, with the reason.</dd><dt>Nudge</dt><dd>Highlights exactly where to look next — single cell with one candidate, or a row/column/box where a number must live. <b>Fill hint</b> places one of the highlighted cells for you.</dd><dt>Check</dt><dd>Verify your entries. Red cells clash or disagree with the solution.</dd><dt>Clear Cell / Undo</dt><dd>Empty the selected cell / take back the last change. A wrong entry also gets a ↩ badge on its cell: tap it to remove just that number and restore the cell's candidates. Printed numbers cannot be cleared while solving.</dd><dt>Edit givens</dt><dd>Go back and fix copied numbers, then Done Editing.</dd><dt>Refresh / Show photo</dt><dd>Reload the daily puzzles / show the newspaper photo behind the grid.</dd><dt>Aa / ?</dt><dd>Toggle large text / open this guide.</dd></dl><h3>Reading the board</h3><p class="help-p">Dark navy = printed. Blue = yours. Red = wrong. Green = hint. Purple = nudge. Tiny digits = pencil marks.</p><h3>Tips</h3><ul class="help-tips"><li>Copy at least 17 printed numbers, or the puzzle may have many solutions.</li><li>Stuck? Go Auto Candidates, then Nudge, then Hint — in that order.</li><li>Press Check after a tricky stretch.</li><li>Solve scope by scope: Box first, then Row, then Entire Grid.</li><li>Works offline; press Refresh when back online. The app updates itself — see Updates, bottom right.</li></ul></div></div>`;}
async function load(manual){const urls=['https://raw.githubusercontent.com/Reboot2004/Sudoku_App/main/frontend/public/data/today.json','https://cdn.jsdelivr.net/gh/Reboot2004/Sudoku_App@main/frontend/public/data/today.json','/data/today.json'];for(const u of urls){try{const r=await fetch(u+(u.includes('?')?'&':'?')+'_='+Date.now(),{cache:'no-store'});if(!r.ok)continue;const d=await r.json();if(!d||!Array.isArray(d.puzzles)||!d.puzzles.length)continue;const base=u.startsWith('http')?u.slice(0,u.indexOf('/data/today.json')):'';state.dataDate=d.date;const sv=readSave();state.dc=d.puzzles.map((p,idx)=>{const q=Object.assign({},p);if(base&&typeof q.image==='string'&&q.image.startsWith('/'))q.image=base+q.image;const fresh=makePuzzle(q,`Deccan Chronicle · ${d.date}`);if(sv&&sv.dcDate===d.date&&sv.dcSnaps&&sv.dcSnaps[idx]){try{const saved=restore(JSON.parse(sv.dcSnaps[idx]));const freshGivens=fresh.cells.map(c=>c.given?c.value:0).join(','),savedGivens=saved.cells.map(c=>c.given?c.value:0).join(',');if(freshGivens!==savedGivens&&freshGivens.split(',').filter(v=>v!=='0').length>savedGivens.split(',').filter(v=>v!=='0').length) return fresh;if(freshGivens!==savedGivens&&fresh.verified&&!saved.verified) return fresh;if(freshGivens!==savedGivens){let diff=0;for(let i=0;i<81;i++) if(fresh.cells[i].given!==saved.cells[i].given||(fresh.cells[i].given&&fresh.cells[i].value!==saved.cells[i].value)) diff++;if(diff>3) return fresh;}return saved;}catch{}}fillAll(fresh);return fresh;});if(sv&&sv.personal){try{state.personal=restore(JSON.parse(sv.personal));state.phase=sv.personalPhase==='input'?'input':'solve';}catch{}}if(sv&&sv.dcDate===d.date)state.dcIndex=Math.min(sv.dcIndex||0,state.dc.length-1);else state.dcIndex=0;if(manual&&sv&&sv.dcDate!==d.date)state.message=`New puzzles loaded · ${d.date}.`;else state.message=`Today's puzzles · ${d.date}.`;save();return render();}catch{}}const sv0=readSave();if(sv0&&sv0.dcSnaps&&sv0.dcSnaps.length){try{state.dataDate=sv0.dcDate||'';state.dc=sv0.dcSnaps.map(s=>restore(JSON.parse(s)));state.dcIndex=Math.min(sv0.dcIndex||0,state.dc.length-1);if(sv0.personal){state.personal=restore(JSON.parse(sv0.personal));state.phase=sv0.personalPhase==='input'?'input':'solve';}state.message=`Offline — showing saved ${state.dataDate} puzzles.`;save();return render();}catch{}}state.dc=[];state.message='Could not load daily puzzles. Check connection and retry.';render();}
